select buss_number ,part_code ,sum(COALESCE( a.quantity,1)) quantity,max(primary_key) primary_key, sum(coalesce( a.quantity, 1)*coalesce( a.task_num, 0)) task_num, sum(coalesce( a.finish_Num, 0)) finish_Num, max(create_time) create_time from ${dynamicTableNameProxy.productSnapshot} a where a.enterprise_code = ${dynamicTableNameProxy.enterpriseCode} and a.delete_flag =false
and buss_number like '%'|| #{data.contractNumber} ||'%'
and ${dynamicTableNameProxy.getXiHangPartQuery("a.part_code","xihang",data.partUnityNo)}
and ${dynamicTableNameProxy.getProductPartSearchObj("a.part_code",data.searchName)}
and exists( select 1 from ${dynamicTableNameProxy.dispatchTaskProduct} b where b.primary_key =a.business_id and b.delete_flag=false
and coalesce(b.remain_quantity,0)>0
and b.Product_Deliver <= #{data.endDate}
and b.Product_Deliver >= #{data.startDate}
) and delete_flag=false and a.task_Num*a.quantity > COALESCE( a.finish_Num,0) and a.part_code is not null group by buss_number ,part_code order by create_time desc

select buss_number ,procedure_code ,array_to_string(part_codes, ',') part_codes , max(primary_key) primary_key ,max(create_time) create_time,array_to_string(ARRAY_AGG(array_to_string(primary_keys,',')),',' ) primary_keys from ( select buss_number ,procedure_code , ARRAY_AGG( distinct COALESCE( part_code,0) ORDER BY COALESCE( part_code,0)) part_codes ,max(primary_key) primary_key,max(create_time) create_time ,ARRAY_AGG(primary_key) primary_keys from ${dynamicTableNameProxy.productSnapshot} a
where a.enterprise_code = ${dynamicTableNameProxy.enterpriseCode} and a.delete_flag =false and a.procedure_code!=0
and exists( select 1 from ${dynamicTableNameProxy.productPartProcedure} b where a.procedure_code=b.primary_key and b.number like '%'|| #{data.partUnityNo} ||'%' )
and exists( select 1 from ${dynamicTableNameProxy.productPartProcedure} b where a.procedure_code=b.primary_key and b.product_part_procedure_sign like '%'|| #{data.searchName} ||'%' )
and buss_number like '%'|| #{data.contractNumber} ||'%'
and procedure_nature =#{data.natureCode}
and exists( select 1 from ${dynamicTableNameProxy.dispatchTaskProduct} b where b.primary_key =a.business_id and b.delete_flag=false
and coalesce(b.remain_quantity,0)>0
and b.Product_Deliver <= #{data.endDate}
and b.Product_Deliver >= #{data.startDate}
) and delete_flag=false and a.procedure_code is not null and a.task_Num > COALESCE( a.process_finish_num,0)
group by buss_number ,business_id ,procedure_code ) group by buss_number ,procedure_code ,part_codes order by create_time desc ,buss_number desc

with a as (select product_code, procedure_code, ARRAY_AGG(distinct coalesce(part_code,0) ORDER BY coalesce(part_code,0)) part_codes
           from ${dynamicTableNameProxy.productSnapshot}
           where procedure_code = #{procedureCode}
             and business_id = #{businessId}
             and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
             and delete_flag = false
             and task_Num > COALESCE(process_finish_num, 0)
           group by product_code, procedure_code),

     b as (select product_code
                , procedure_code
                , ARRAY_AGG(distinct coalesce(part_code,0) ORDER BY coalesce(part_code,0)) part_codes
                , max(primary_key)                                 primary_key
                , buss_number
           from ${dynamicTableNameProxy.productSnapshot}
           where procedure_code = #{procedureCode}
             and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
             and delete_flag = false
             and task_Num > COALESCE(process_finish_num, 0)
           group by buss_number, product_code, procedure_code)
select b.*
from a,
     b
where a.product_code = b.product_code
  and a.part_codes = b.part_codes

