set Process_Finish_Num = COALESCE(#{data.processFinishNum}, 0),
    Finish_Num         =COALESCE(#{data.finishNum}, 0)

where primary_key = #{data.primaryKey}

  and task_num >= COALESCE(#{data.processFinishNum}, 0)
  and task_num * quantity >= COALESCE(#{data.finishNum}, 0)

